package com.nigson.integration.notification;

import java.time.*;
import java.sql.Timestamp;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.*;
import tools.jackson.databind.JsonNode;
import com.nigson.integration.platform.AuditWriter;
import com.nigson.integration.providers.TwilioAccount;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.ProviderHttp;
import io.micrometer.core.instrument.MeterRegistry;

/** Paired owner-local leases and write checkpoint. No HTTP executes within these transactions. */
public final class VerificationExecution {
 public record Claim(UUID id,UUID verification,UUID correlation,String channel,long jobVersion,long dispatchVersion,Instant lease,boolean compatible,boolean maySend,String sid,JsonNode template){public Claim{template=template.deepCopy();}@Override public JsonNode template(){return template.deepCopy();}@Override public String toString(){return "VerificationClaim[protected]";}}
 private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final AuditWriter audit;private final Clock clock;private final ProviderHttp.Mode transport;private final String mode,accountHash;private final UUID generation;private final Instant notBefore;private final MeterRegistry metrics;
 public VerificationExecution(JdbcTemplate jdbc,PlatformTransactionManager manager,AuditWriter audit,Clock clock,ProviderHttp.Mode mode,String accountHash,UUID generation,Instant notBefore,MeterRegistry metrics){
  if(mode==null||accountHash==null||!accountHash.matches("[a-f0-9]{64}")||generation==null||generation.equals(new UUID(0,0))||notBefore==null)throw new IllegalArgumentException("MESSAGE_EXECUTION_IDENTITY_REQUIRED");this.jdbc=Objects.requireNonNull(jdbc);tx=new TransactionTemplate(manager);tx.setTimeout(5);this.audit=Objects.requireNonNull(audit);this.clock=Objects.requireNonNull(clock);transport=mode;this.mode=mode==ProviderHttp.Mode.TEST?"SANDBOX":mode.name();this.accountHash=accountHash;this.generation=generation;this.notBefore=notBefore;this.metrics=Objects.requireNonNull(metrics);
 }
 public boolean matches(ProviderHttp.Mode mode,String hash){return transport==mode&&accountHash.equals(hash);}
 private void local(){jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");}
 private Timestamp now(){return Timestamp.from(clock.instant());}
 private static long version(Map<String,Object> r){return ((Number)r.get("version")).longValue();}
 private static int attempts(Map<String,Object> r){return ((Number)r.get("attempt_count")).intValue();}
 private Claim claim(Map<String,Object> j,Map<String,Object> d,boolean compatible,boolean fresh){return new Claim((UUID)j.get("id"),(UUID)j.get("resource_id"),(UUID)d.get("correlation_id"),(String)j.get("channel"),version(j),version(d),((Timestamp)d.get("lease_until")).toInstant(),compatible,fresh,(String)d.get("provider_message_id"),EventCodec.JSON.readTree(d.get("template_snapshot").toString()));}
 private boolean identity(Map<String,Object> j,Map<String,Object> d){
  try{var template=EventCodec.JSON.readTree(d.get("template_snapshot").toString());return accountHash.equals(d.get("account_hash"))&&accountHash.equals(TwilioAccount.fingerprint(transport,(String)d.get("account_sid"),(String)d.get("messaging_service_sid")))&&mode.equals(j.get("provider_mode"))&&template.isObject()&&template.propertyNames().equals(Set.of("id","code","revision","locale","channel","classification","body","providerTemplateId","variablesSchema"))&&d.get("template_hash").equals(EventCodec.hash(template))&&template.path("id").asString().equals(d.get("template_id").toString())&&template.path("locale").asString().equals(d.get("locale"))&&template.path("channel").asString().equals(j.get("channel"))&&template.path("revision").asInt()==((Number)j.get("template_revision")).intValue()&&"CONTACT_VERIFICATION".equals(template.path("code").asString())&&"TRANSACTIONAL".equals(template.path("classification").asString())&&VerificationRequestedHandler.job((UUID)j.get("resource_id")).equals(j.get("id"))&&Objects.equals(j.get("provider_reference"),d.get("provider_message_id"));}catch(RuntimeException malformed){return false;}
 }
 private boolean fresh(Map<String,Object> j,Map<String,Object> d){return identity(j,d)&&"INTENT".equals(d.get("stage"))&&attempts(j)==0&&attempts(d)==0&&d.get("submitted_at")==null&&d.get("request_hash")==null&&d.get("provider_message_id")==null&&generation.equals(d.get("generation"))&&!((Timestamp)d.get("source_occurred_at")).toInstant().isBefore(notBefore)&&!((Timestamp)d.get("source_occurred_at")).toInstant().isAfter(clock.instant().plusSeconds(30));}
 public Optional<Claim> claim(){return claim(null);}
 Optional<Claim> claim(UUID selected){return tx.execute(status->{local();var jobs=jdbc.queryForList("SELECT * FROM integration.notification_job WHERE owner_service='experience' AND template_code='CONTACT_VERIFICATION' AND classification='TRANSACTIONAL' AND channel IN ('SMS','WHATSAPP') AND state IN ('PENDING','CLAIMED','SENT','UNKNOWN') AND next_attempt_at<=? AND (lease_until IS NULL OR lease_until<=?) AND (?::uuid IS NULL OR id=?::uuid) ORDER BY next_attempt_at,id LIMIT 1 FOR UPDATE SKIP LOCKED",now(),now(),selected,selected);if(jobs.isEmpty())return Optional.empty();var j=jobs.getFirst();UUID id=(UUID)j.get("id");var intents=jdbc.queryForList("SELECT * FROM integration.notification_dispatch WHERE id=? FOR UPDATE",id);if(intents.size()!=1){jdbc.update("UPDATE integration.notification_job SET state='UNKNOWN',lease_until=NULL,next_attempt_at=?,version=version+1,updated_at=?,updated_by='verification-worker' WHERE id=?",Timestamp.from(clock.instant().plusSeconds(300)),now(),id);evidence(id,UUID.nameUUIDFromBytes(("missing-intent:"+id).getBytes(java.nio.charset.StandardCharsets.US_ASCII)),"UNKNOWN");return Optional.empty();}var d=intents.getFirst();if(d.get("lease_until")!=null&&((Timestamp)d.get("lease_until")).toInstant().isAfter(clock.instant()))return Optional.empty();boolean compatible=identity(j,d),send="PENDING".equals(j.get("state"))&&j.get("lease_until")==null&&d.get("lease_until")==null&&fresh(j,d);Instant lease=clock.instant().plusSeconds(60);
  jdbc.update("UPDATE integration.notification_job SET state='CLAIMED',lease_until=?,version=version+1,updated_at=?,updated_by='verification-worker' WHERE id=?",Timestamp.from(lease),now(),id);jdbc.update("UPDATE integration.notification_dispatch SET lease_until=?,version=version+1,updated_at=?,updated_by='verification-worker' WHERE id=?",Timestamp.from(lease),now(),id);evidence(id,(UUID)d.get("correlation_id"),"CLAIMED");return Optional.of(claim(jdbc.queryForMap("SELECT * FROM integration.notification_job WHERE id=?",id),jdbc.queryForMap("SELECT * FROM integration.notification_dispatch WHERE id=?",id),compatible,send));});}
 private List<Map<String,Object>> lock(Claim c){local();var jobs=jdbc.queryForList("SELECT * FROM integration.notification_job WHERE id=? FOR UPDATE",c.id());var intents=jdbc.queryForList("SELECT * FROM integration.notification_dispatch WHERE id=? FOR UPDATE",c.id());if(jobs.size()!=1||intents.size()!=1)return List.of();var j=jobs.getFirst();var d=intents.getFirst();if(version(j)!=c.jobVersion()||version(d)!=c.dispatchVersion()||!"CLAIMED".equals(j.get("state"))||j.get("lease_until")==null||d.get("lease_until")==null||!((Timestamp)j.get("lease_until")).toInstant().equals(c.lease())||!((Timestamp)d.get("lease_until")).toInstant().equals(c.lease())||!c.lease().isAfter(clock.instant()))return List.of();return List.of(j,d);}
 public Optional<Claim> prepare(Claim c,VerificationMessage.Request request,Instant approvedUntil){if(request==null||approvedUntil==null||!c.maySend()||!c.compatible())throw rule();return tx.execute(status->{var rows=lock(c);if(rows.isEmpty())return Optional.empty();var j=rows.get(0);var d=rows.get(1);if(!fresh(j,d)||!c.channel().equals(request.channel())||!request.hash().matches("[a-f0-9]{64}")||!request.expiresAt().isAfter(clock.instant().plusSeconds(10))||!approvedUntil.isAfter(clock.instant().plusSeconds(15))||!c.lease().isAfter(clock.instant().plusSeconds(15)))throw rule();var templates=jdbc.queryForList("SELECT * FROM integration.notification_template WHERE id=? AND active FOR SHARE",d.get("template_id"));if(templates.size()!=1)throw rule();var t=templates.getFirst();var frozen=c.template();if(!Objects.equals(t.get("body"),frozen.path("body").asString())||!Objects.equals(t.get("provider_template_id"),frozen.path("providerTemplateId").isNull()?null:frozen.path("providerTemplateId").asString())||!EventCodec.JSON.readTree(t.get("variables_schema").toString()).equals(frozen.path("variablesSchema"))||!"CONTACT_VERIFICATION".equals(t.get("code"))||!"TRANSACTIONAL".equals(t.get("classification"))||!c.channel().equals(t.get("channel"))||!d.get("locale").equals(t.get("locale"))||!j.get("template_revision").equals(t.get("revision")))throw rule();
  jdbc.update("UPDATE integration.notification_job SET attempt_count=1,version=version+1,updated_at=?,updated_by='verification-worker' WHERE id=?",now(),c.id());jdbc.update("UPDATE integration.notification_dispatch SET stage='SUBMITTING',attempt_count=1,submitted_at=?,request_hash=?,version=version+1,updated_at=?,updated_by='verification-worker' WHERE id=?",now(),request.hash(),now(),c.id());evidence(c.id(),c.correlation(),"SUBMITTING");return Optional.of(claim(jdbc.queryForMap("SELECT * FROM integration.notification_job WHERE id=?",c.id()),jdbc.queryForMap("SELECT * FROM integration.notification_dispatch WHERE id=?",c.id()),true,false));});}
 /** Pre-write context outage may defer the original intent; definite source denial suppresses it. */
 public boolean beforeSendFailed(Claim c,boolean suppress){return Boolean.TRUE.equals(tx.execute(status->{var rows=lock(c);if(rows.isEmpty())return false;if(!c.maySend()||!fresh(rows.get(0),rows.get(1)))throw rule();String state=suppress?"SUPPRESSED":"PENDING",stage=suppress?"SUPPRESSED":"INTENT";finish(c,state,stage,null,suppress?"CONSENT_RULE_VIOLATION":"PROVIDER_UNAVAILABLE",false,0);return true;}));}
 public boolean unknown(Claim c,String error){if(!Set.of("PROVIDER_OUTCOME_UNKNOWN","PROVIDER_MODE_MISMATCH").contains(error))throw rule();return Boolean.TRUE.equals(tx.execute(status->{var rows=lock(c);if(rows.isEmpty())return false;finish(c,"UNKNOWN","UNKNOWN",(String)rows.get(1).get("provider_message_id"),error,attempts(rows.get(1))>0,0);return true;}));}
 public boolean outcome(Claim c,JsonNode output,int durationMs){if(output==null||durationMs<0)throw rule();String sid=output.path("sid").asString(),providerState=output.path("status").asString();if(!sid.matches("SM[a-fA-F0-9]{32}")||!Set.of("accepted","scheduled","queued","sending","sent","delivered","read","failed","undelivered","canceled").contains(providerState)||c.sid()!=null&&!c.sid().equals(sid))throw rule();return Boolean.TRUE.equals(tx.execute(status->{var rows=lock(c);if(rows.isEmpty())return false;var j=rows.get(0);var d=rows.get(1);if(!identity(j,d)||attempts(d)!=1||d.get("request_hash")==null||!Set.of("SUBMITTING","ACCEPTED","UNKNOWN").contains(d.get("stage"))||d.get("provider_message_id")!=null&&!sid.equals(d.get("provider_message_id")))throw rule();String state=Set.of("delivered","read").contains(providerState)?"DELIVERED":Set.of("failed","undelivered","canceled").contains(providerState)?"FAILED":"SENT";finish(c,state,state.equals("FAILED")?"FAILED":"ACCEPTED",sid,null,true,durationMs);return true;}));}
 private void finish(Claim c,String state,String stage,String sid,String error,boolean attempt,int durationMs){Timestamp due=Timestamp.from(clock.instant().plusSeconds(state.equals("UNKNOWN")?300:30));jdbc.update("UPDATE integration.notification_job SET state=?,provider_reference=?,lease_until=NULL,next_attempt_at=?,version=version+1,updated_at=?,updated_by='verification-worker' WHERE id=?",state,sid,due,now(),c.id());jdbc.update("UPDATE integration.notification_dispatch SET stage=?,provider_message_id=?,error_code=?,lease_until=NULL,next_attempt_at=?,version=version+1,updated_at=?,updated_by='verification-worker' WHERE id=?",stage,sid,error,due,now(),c.id());if(attempt)jdbc.update("INSERT INTO integration.notification_attempt(id,created_by,job_id,attempt_number,provider,provider_message_id,result,error_code,duration_ms,channel) VALUES (?,'verification-worker',?,1,'TWILIO',?,?,?,?,?) ON CONFLICT (job_id,attempt_number) DO NOTHING",EventCodec.uuid7(clock.instant()),c.id(),sid,state,error,durationMs,c.channel());evidence(c.id(),c.correlation(),state);}
 private void evidence(UUID id,UUID correlation,String state){audit.append("verification-worker",AuditValues.ActorKind.SYSTEM,AuditValues.Action.QUEUE_REPLAY,AuditValues.Resource.NOTIFICATION,id,correlation,AuditValues.Reason.RECONCILIATION,null,Map.of("state",state),null);TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.notification.verification","state",state).increment();}});}
 private static Problem.Failure rule(){return new Problem.Failure(ProblemCode.NOTIFICATION_RULE_VIOLATION);}
}
